import re
css=open('styles/styles.css').read()
for m in re.finditer(r'([^{}]*g-root_theme_(?:light|dark)\b[^{}]*)\{([^}]*)\}',css):
    sel=m.group(1).strip()[-80:]
    body=m.group(2)
    for v in ['base-background','text-primary','text-secondary','text-complementary','text-hint','line-generic','line-generic-solid','base-generic']:
        mm=re.search(r'--g-color-'+v+r':\s*([^;]+);',body)
        if mm: print(sel,'|',v,mm.group(1))
EOF

